/* @lc app=leetcode id=1931 lang=kotlin */ class Solution { fun colorTheGrid(m: Int, n: Int): Int = intArrayOf(1, 3, 9, 27, 81, 243).let { p3 -> (0 until p3[m]).filter { mask -> (0 until m - 1).all { i -> (mask / p3[i]) % 3 != (mask / p3[i + 1]) % 3 } }.let { states -> states.map { u -> states.indices.filter { vi -> (0 until m).all { i -> (u / p3[i]) % 3 != (states[vi] / p3[i]) % 3 } }.toIntArray() }.let { adj -> (1 until n).fold(LongArray(states.size) { 1L }) { dp, _ -> LongArray(states.size) { i -> adj[i].sumOf { j -> dp[j] } % 1000000007L } }.sum() % 1000000007L }.toInt() } } }